
const API_BASE=(localStorage.getItem("carShopApiBase")||"/api").replace(/\/$/,"");
const SUPER_SESSION_KEY="carDealerSuperCloudSession_v1";
const AUTO_REFRESH_MS=3000;
let superToken="",currentPage="overview",cloudRows=[],healthRows=[],diagnosticRows=[],globalSchema=null,updatePolicy=null,updateEventRows=[],backupData=null,haData=null,loadTestData=null,performanceData=null,resilienceData=null,resilienceSuiteData=null,securityData=null,securityAuditData=null,securityReleaseRows=[],securityAuditPage=1,commercialData=null,commercialPilotPage=1,subscriptionData=null,subscriptionPlanPage=1,subscriptionPlanSearch='',subscriptionPlanStatus='',subscriptionDealerPage=1,subscriptionDealerSearch='',subscriptionDealerStatus='',subscriptionPaymentPage=1,subscriptionPaymentSearch='',subscriptionPaymentStatus='',refreshing=false,lastCloudAt=0,lastDiagnosticsAt=0,lastBackupsAt=0,lastHaAt=0,lastLoadTestAt=0,lastPerformanceAt=0,lastResilienceAt=0,resiliencePollTimer=null;
const nodeCompanyCache=new Map(),nodeVehicleCache=new Map();

function today(){const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]))}
function money(v){return "$"+Number(v||0).toLocaleString("zh-TW")}
function rate(v){const n=Number(v||0);return Number.isInteger(n)?String(n):n.toFixed(2).replace(/0+$/,"").replace(/\.$/,"")}
function badgeFor(st){return st==="啟用中"?"ok":st==="尚未啟用"?"warn":"bad"}
function setCloudState(text,kind="info"){const el=document.getElementById("cloudState");if(!el)return;el.className="badge "+kind;el.textContent=text}
function getSession(){try{return JSON.parse(localStorage.getItem(SUPER_SESSION_KEY)||"null")}catch{return null}}
function saveSession(){if(!superToken)return;localStorage.setItem(SUPER_SESSION_KEY,JSON.stringify({token:superToken,page:currentPage,savedAt:Date.now()}))}

async function api(path,options={}){
  const headers={"Content-Type":"application/json",...(options.headers||{})};
  if(superToken)headers.Authorization="Bearer "+superToken;
  let res;
  try{res=await fetch(API_BASE+path,{...options,headers})}
  catch(e){throw new Error("無法連線中央伺服器，請確認網路或 Render 狀態")}
  let body={};try{body=await res.json()}catch{}
  if(res.status===401&&superToken){logout("Super Admin 登入已失效，請重新登入");throw new Error(body.error||"登入已失效")}
  if(!res.ok)throw new Error(body.error||("HTTP "+res.status));
  return body;
}

function companyDataRow(id){return cloudRows.find(x=>x.company?.id===id)||null}
function allCars(){const arr=[];for(const x of cloudRows){const cars=Array.isArray(x.snapshot?.cars)?x.snapshot.cars:[];for(const car of cars)arr.push({...car,_companyId:x.company.id,_companyName:x.company.name})}return arr}
function allUsers(){const arr=[];for(const x of cloudRows){const users=Array.isArray(x.users)&&x.users.length?x.users:(Array.isArray(x.snapshot?.users)?x.snapshot.users:[]);for(const u of users)arr.push({...u,_companyId:x.company.id,_companyName:x.company.name})}return arr}
function soldCars(){return allCars().filter(c=>c.status==="已售"||Number(c.sellPrice)>0)}
function nodeIsOnline(x){if(x?.node?.capabilities?.online===false)return false;const t=Date.parse(x?.node?.last_seen_at||"");return Number.isFinite(t)&&(Date.now()-t)<45000}
function nodeStatusHtml(x){if(!x?.node)return `<span class="badge warn">尚未建立節點</span>`;return nodeIsOnline(x)?`<span class="badge ok node-live">● Node 在線</span>`:`<span class="badge bad">● Node 離線</span>`}
function fmtDateTime(v){if(!v)return "-";try{const d=new Date(v);if(!Number.isFinite(d.getTime())||d.getTime()<946684800000)return "-";return d.toLocaleString("zh-TW",{hour12:false})}catch{return "-"}}
async function requestNodeData(companyId,resource,payload={}){
 const start=await api(`/super/nodes/${encodeURIComponent(companyId)}/request`,{method:"POST",body:JSON.stringify({resource,payload})});
 const id=start.requestId,deadline=Date.now()+18000;
 while(Date.now()<deadline){
   await new Promise(r=>setTimeout(r,500));
   const r=await api(`/super/node-requests/${encodeURIComponent(id)}`);
   if(r.status==="completed")return r.result;
   if(["failed","expired"].includes(r.status))throw new Error(r.error||"Dealer Node 讀取失敗");
 }
 throw new Error("Dealer Node 回應逾時");
}
function loadingNode(title,sub="正在透過中央控制通道向車行電腦讀取本機資料…"){
 modal.innerHTML=`<div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div><h2 style="margin:0">${esc(title)}</h2><div class="muted">Dealer Node 即時讀取</div></div><button class="btn2" onclick="closeModal()">關閉</button></div><div class="node-loading"><div class="spinner"></div><div><b>正在讀取</b><div class="muted">${esc(sub)}</div></div></div>`;modalBg.classList.add("show")
}

async function doLogin(){
  const u=loginUser.value.trim(),p=loginPass.value;
  if(!u||!p){alert("請輸入 Super Admin 帳號與密碼");return}
  try{
    setLoginBusy(true);
    const health=await fetch(API_BASE+"/health");if(!health.ok)throw new Error("中央伺服器目前無法使用");
    const r=await fetch(API_BASE+"/super/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:u,password:p})});
    let b={};try{b=await r.json()}catch{}
    if(!r.ok)throw new Error(b.error||"登入失敗");
    superToken=b.token;
    currentPage="overview";
    saveSession();
    loginPass.value="";
    loginPage.style.display="none";app.style.display="block";
    await refreshCloud(false);
    showPage("overview");
  }catch(e){alert(e.message)}finally{setLoginBusy(false)}
}
function setLoginBusy(v){const b=document.querySelector("#loginPage .btn");if(b){b.disabled=v;b.textContent=v?"連線登入中…":"登入超級管理後台"}}
function logout(reason=""){
  superToken="";cloudRows=[];localStorage.removeItem(SUPER_SESSION_KEY);
  app.style.display="none";loginPage.style.display="flex";loginPass.value="";setCloudState("尚未連線","warn");
  if(reason)alert(reason);
}
async function restoreSession(){
  const s=getSession();if(!s?.token)return false;
  superToken=s.token;currentPage=s.page||"overview";
  loginPage.style.display="none";app.style.display="block";
  try{await refreshCloud(false);showPage(currentPage);return true}catch(e){logout();return false}
}
loginPass.addEventListener("keydown",e=>{if(e.key==="Enter")doLogin()});

function showPage(p){
  currentPage=p;saveSession();
  ["overview","vehicles","sales","users","subscriptions","health","diagnostics","updates","backups","ha","loadtest","performance","resilience","security","commercial"].forEach(x=>document.getElementById("nav"+x[0].toUpperCase()+x.slice(1)).classList.toggle("active",x===p));
  const adv=document.getElementById("advancedOps");if(adv&&["ha","loadtest","performance","resilience","commercial"].includes(p))adv.open=true;
  const titles={overview:"車行總覽",vehicles:"全部車輛",sales:"全部成交",users:"全部帳號",subscriptions:"訂閱與授權",health:"系統健康",diagnostics:"錯誤診斷",updates:"版本更新",backups:"中央備份",ha:"容災架構",loadtest:"壓力測試",performance:"效能監控",resilience:"故障演練",security:"安全與稽核",commercial:"商用上線"};pageTitle.textContent=titles[p]||"Super Admin";
  if(p==="diagnostics"&&Date.now()-lastDiagnosticsAt>5000)refreshDiagnostics(false);else if(p==="backups"&&Date.now()-lastBackupsAt>5000)refreshBackups(false);else if(p==="ha"&&Date.now()-lastHaAt>5000)refreshHa(false);else if(p==="loadtest"&&Date.now()-lastLoadTestAt>5000)refreshLoadTests(false);else if(p==="performance"&&Date.now()-lastPerformanceAt>3000)refreshPerformance(false);else if(p==="resilience"&&Date.now()-lastResilienceAt>3000)refreshResilience(false);else if(p==="security")refreshSecurity(false);else if(p==="commercial")refreshCommercial(false);else if(p==="subscriptions")refreshSubscriptions(false);else renderCurrent();
}
function renderCurrent(){if(currentPage==="overview")renderOverview();else if(currentPage==="vehicles")renderVehicles();else if(currentPage==="sales")renderSales();else if(currentPage==="users")renderUsers();else if(currentPage==="health")renderHealth();else if(currentPage==="diagnostics")renderDiagnostics();else if(currentPage==="updates")renderUpdates();else if(currentPage==="backups")renderBackups();else if(currentPage==="ha")renderHa();else if(currentPage==="loadtest")renderLoadTests();else if(currentPage==="performance")renderPerformance();else if(currentPage==="resilience")renderResilience();else if(currentPage==="security")renderSecurity();else if(currentPage==="commercial")renderCommercial();else if(currentPage==="subscriptions")renderSubscriptions()}
function userIsEditing(){const a=document.activeElement;return !!(a&&(a.tagName==="INPUT"||a.tagName==="SELECT"||a.tagName==="TEXTAREA"||a.isContentEditable))}
function modalIsOpen(){return modalBg.classList.contains("show")}

// Super Admin auto-refresh must never fight the operator's scroll position.
let superScrollInteractionUntil=0,superScrollbarDragging=false;
function markSuperScrollInteraction(ms=2200){superScrollInteractionUntil=Math.max(superScrollInteractionUntil,Date.now()+ms)}
function userIsScrolling(){return superScrollbarDragging||Date.now()<superScrollInteractionUntil}
document.addEventListener("wheel",e=>{if(app.style.display!=="none")markSuperScrollInteraction()}, {passive:true,capture:true});
document.addEventListener("touchmove",e=>{if(app.style.display!=="none")markSuperScrollInteraction()}, {passive:true,capture:true});
document.addEventListener("scroll",e=>{if(app.style.display!=="none")markSuperScrollInteraction()}, true);
document.addEventListener("pointerdown",e=>{if(e.target?.closest?.(".table-wrap")){superScrollbarDragging=true;markSuperScrollInteraction(10000)}}, true);
document.addEventListener("pointerup",()=>{if(superScrollbarDragging){superScrollbarDragging=false;markSuperScrollInteraction()}}, true);
document.addEventListener("pointercancel",()=>{superScrollbarDragging=false;markSuperScrollInteraction()}, true);

function captureSuperScrollState(){
  return {
    page:currentPage,
    x:window.scrollX||document.documentElement.scrollLeft||0,
    y:window.scrollY||document.documentElement.scrollTop||0,
    tables:Array.from(document.querySelectorAll("#main .table-wrap")).map((el,i)=>({i,left:el.scrollLeft,top:el.scrollTop}))
  };
}
function restoreSuperScrollState(s){
  if(!s||s.page!==currentPage)return;
  const restore=()=>{
    window.scrollTo(s.x,s.y);
    const tables=document.querySelectorAll("#main .table-wrap");
    for(const p of s.tables||[]){const el=tables[p.i];if(el){el.scrollLeft=p.left;el.scrollTop=p.top}}
  };
  restore();
  requestAnimationFrame(restore);
}
function renderCurrentPreservingScroll(){
  const s=captureSuperScrollState();
  renderCurrent();
  restoreSuperScrollState(s);
}

async function refreshCloud(manual=false){
  if(!superToken||refreshing)return;
  refreshing=true;
  try{
    const [r,h,u,ue]=await Promise.all([api("/super/data"),api("/super/health"),api("/super/update-policy"),api("/super/update-events?limit=300")]);cloudRows=Array.isArray(r.companies)?r.companies:[];healthRows=Array.isArray(h.health)?h.health:[];globalSchema=h.schema||null;updatePolicy=u.policy||h.updatePolicy||null;updateEventRows=Array.isArray(ue.events)?ue.events:[];lastCloudAt=Date.now();setCloudState("雲端已同步","ok");saveSession();
    if(currentPage==="diagnostics"){try{const dg=await api('/super/diagnostics?limit=300');diagnosticRows=Array.isArray(dg.events)?dg.events:[];lastDiagnosticsAt=Date.now()}catch{}}
    // Data can keep refreshing in the background, but never redraw while the user is dragging/scrolling.
    // When redraw is safe, preserve both vertical page position and each table's horizontal/vertical position.
    if(manual)renderCurrentPreservingScroll();
    else if(!modalIsOpen()&&!userIsEditing()&&!userIsScrolling())renderCurrentPreservingScroll();
  }catch(e){setCloudState("連線異常","bad");if(manual)alert(e.message);throw e}
  finally{refreshing=false}
}


async function refreshDiagnostics(manual=false){
  if(!superToken)return;
  try{
    const r=await api('/super/diagnostics?limit=300');
    diagnosticRows=Array.isArray(r.events)?r.events:[];lastDiagnosticsAt=Date.now();
    if(currentPage==='diagnostics')renderCurrentPreservingScroll();
  }catch(e){if(manual)alert(e.message||'讀取診斷資料失敗')}
}
function diagnosticBadge(sev){const s=String(sev||'error');return `<span class="badge ${s==='info'?'info':s==='warn'?'warn':'bad'}">${esc(s)}</span>`}
function renderDiagnostics(){
  const rows=[...diagnosticRows];
  const open=rows.filter(x=>!x.resolved),critical=open.filter(x=>x.severity==='critical').length,errors=open.filter(x=>x.severity==='error').length;
  main.innerHTML=`<div class="cards"><div class="card"><div class="muted">未處理診斷</div><div class="num">${open.length}</div></div><div class="card"><div class="muted">Critical</div><div class="num">${critical}</div></div><div class="card"><div class="muted">Error</div><div class="num">${errors}</div></div><div class="card"><div class="muted">最近載入</div><div class="num" style="font-size:18px">${fmtDateTime(new Date(lastDiagnosticsAt||Date.now()).toISOString())}</div></div></div>
  <div class="panel"><div class="panel-head"><div><h2 style="margin:0">🧰 錯誤診斷中心</h2><div class="muted">同類錯誤自動聚合，不洗版；可查看第一次、最後一次與累計次數。密碼、Token、Cookie 等敏感欄位不寫入診斷內容。</div></div><button class="btn2" onclick="refreshDiagnostics(true)">重新整理</button></div>
  <div class="tools" style="margin:12px 0"><input id="diagQ" placeholder="搜尋車行 / Error Code / 模組 / 訊息" oninput="filterDiagnostics()"><select id="diagSeverity" onchange="filterDiagnostics()"><option value="">全部嚴重度</option><option>critical</option><option>error</option><option>warn</option><option>info</option></select><select id="diagState" onchange="filterDiagnostics()"><option value="open">未處理</option><option value="">全部</option><option value="resolved">已處理</option></select></div>
  <div class="table-wrap"><table><thead><tr><th>最後發生</th><th>車行</th><th>Error Code</th><th>模組</th><th>等級</th><th>訊息</th><th>版本</th><th>次數</th><th>第一次</th><th>狀態</th><th>操作</th></tr></thead><tbody id="diagRows">${rows.map(d=>`<tr data-search="${esc(((d.company_name||d.company_id||'')+' '+d.error_code+' '+d.module+' '+d.message).toLowerCase())}" data-sev="${esc(d.severity||'')}" data-resolved="${d.resolved?'1':'0'}"><td>${fmtDateTime(d.last_seen_at)}</td><td>${esc(d.company_name||d.company_id||'系統')}<div class="muted"><code>${esc(d.company_id||'-')}</code></div></td><td><code>${esc(d.error_code||'-')}</code></td><td>${esc(d.module||'-')}</td><td>${diagnosticBadge(d.severity)}</td><td style="min-width:260px">${esc(d.message||'-')}</td><td>${esc(d.app_version||'-')}</td><td>${Number(d.occurrence_count||1)}</td><td>${fmtDateTime(d.first_seen_at)}</td><td>${d.resolved?'<span class="badge ok">已處理</span>':'<span class="badge bad">未處理</span>'}</td><td>${d.resolved?'-':`<button class="btn2" onclick="resolveDiagnostic('${d.id}')">標記已處理</button>`}</td></tr>`).join('')||'<tr><td colspan="11">目前沒有診斷事件</td></tr>'}</tbody></table></div></div>`;
  filterDiagnostics();
}
function showCompanyDiagnostics(id){showPage('diagnostics');setTimeout(()=>{const q=document.getElementById('diagQ');if(q){q.value=id;filterDiagnostics()}},150)}
function filterDiagnostics(){const q=(document.getElementById('diagQ')?.value||'').trim().toLowerCase(),sev=document.getElementById('diagSeverity')?.value||'',state=document.getElementById('diagState')?.value||'open';document.querySelectorAll('#diagRows tr[data-search]').forEach(r=>{const okQ=!q||r.dataset.search.includes(q),okS=!sev||r.dataset.sev===sev,okR=!state||(state==='open'?r.dataset.resolved==='0':r.dataset.resolved==='1');r.style.display=okQ&&okS&&okR?'':'none'})}
async function resolveDiagnostic(id){try{await api('/super/diagnostics/'+encodeURIComponent(id)+'/resolve',{method:'POST',body:'{}'});await refreshDiagnostics(true);await refreshCloud(false)}catch(e){alert(e.message||'更新失敗')}}

function remainText(c){if(c.trialRemainingSeconds===null||c.trialRemainingSeconds===undefined)return "不限期";let x=Math.max(0,Number(c.trialRemainingSeconds));const d=Math.floor(x/86400);x%=86400;const h=Math.floor(x/3600);x%=3600;const m=Math.floor(x/60);return `${d}天 ${h}時 ${m}分`;}
async function openOfflineTest(id){const x=companyDataRow(id);if(!x)return;let t={enabled:false,durationSeconds:60,simulateOutage:false};try{t=await api("/super/companies/"+encodeURIComponent(id)+"/offline-test")}catch(e){}const sec=Number(t.durationSeconds||60),hh=String(Math.floor(sec/3600)).padStart(2,"0"),mm=String(Math.floor(sec%3600/60)).padStart(2,"0"),ss=String(sec%60).padStart(2,"0");modal.innerHTML=`<h2>🧪 容錯授權測試｜${esc(x.company.name)}</h2><div class="notice">正式授權容錯固定 72 小時。這裡只影響指定車行的測試憑證，可用時／分／秒快速測試，不會修改其他車行。</div><div class="grid"><label>時<input id="oth" type="number" min="0" value="${hh}"></label><label>分<input id="otm" type="number" min="0" max="59" value="${mm}"></label><label>秒<input id="ots" type="number" min="0" max="59" value="${ss}"></label></div><label style="display:flex;gap:8px;align-items:center;margin-top:16px"><input id="oten" type="checkbox" style="width:auto" ${t.enabled?"checked":""}> 啟用此車行測試模式</label><label style="display:flex;gap:8px;align-items:center;margin-top:12px"><input id="otout" type="checkbox" style="width:auto" ${t.simulateOutage?"checked":""}> 模擬授權服務無回應</label><div class="notice">測試方式：先啟用測試模式但不要勾「模擬無回應」，讓車行成功登入一次取得測試憑證；再勾模擬無回應，即可測試備用登入與到期。</div><div class="actions"><button class="btn2" onclick="closeModal()">取消</button><button class="btn" onclick="saveOfflineTest('${esc(id)}')">儲存測試設定</button></div>`;modalBg.classList.add("show");}
async function saveOfflineTest(id){const sec=Math.max(5,Number(oth.value||0)*3600+Number(otm.value||0)*60+Number(ots.value||0));try{await api("/super/companies/"+encodeURIComponent(id)+"/offline-test",{method:"PUT",body:JSON.stringify({enabled:oten.checked,durationSeconds:sec,simulateOutage:otout.checked})});closeModal();alert("容錯測試設定已更新。") }catch(e){alert(e.message)}}

