async function refreshResilience(showMsg=true){try{if(resiliencePollTimer){clearTimeout(resiliencePollTimer);resiliencePollTimer=null}if(showMsg)setCloudState('正在更新故障演練狀態…','warn');const rr=await Promise.all([api('/super/resilience'),api('/super/resilience/suite')]);resilienceData=rr[0];resilienceSuiteData=rr[1];lastResilienceAt=Date.now();if(showMsg)setCloudState('故障演練狀態已更新','ok');if(currentPage==='resilience')renderCurrentPreservingScroll();const running=(Array.isArray(resilienceSuiteData?.active)&&resilienceSuiteData.active.length>0)||(Array.isArray(resilienceSuiteData?.runs)&&resilienceSuiteData.runs.some(x=>(x.live?.status||x.status)==='running'));if(currentPage==='resilience'&&running){resiliencePollTimer=setTimeout(()=>refreshResilience(false),2000)}}catch(e){if(showMsg)alert(e.message||'讀取故障演練狀態失敗')}}
